<div class="card mb-4"><div class="card-body"><h2 class="h5">Enroll in a section</h2><form method="post" action="/student/enroll" class="row g-2"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><div class="col-sm-8"><input required name="enrollment_code" class="form-control" placeholder="Enter section enrollment code"></div><div class="col-sm-4"><button class="btn btn-primary">Enroll</button></div></form></div></div><h2 class="h5">My sections</h2><div class="list-group"><?php foreach($sections as $s): ?><a class="list-group-item list-group-item-action" href="/student/sections/<?= (int)$s['id'] ?>"><?= e($s['code'].' · '.$s['title'].' — '.$s['name']) ?></a><?php endforeach ?></div><?php if(!$sections): ?><p class="mt-3">No sections yet. Ask your teacher for an enrollment code.</p><?php endif ?>
